import { getCategories, getComponentStats } from '../utils/jsonDataLoader.js';

/**
 * List all available component categories
 */
export async function listCategories(args) {
  const { detailed = false } = args;

  try {
    // Get data from JSON loader
    const categoriesData = getCategories(true);
    const stats = getComponentStats();

    if (!categoriesData) {
      return {
        content: [
          {
            type: 'text',
            text: 'Categories data not available. Please try again later.'
          }
        ]
      };
    }

    // Format response using JSON data
    const responseText = formatCategoriesResponseFromJson(categoriesData, stats, detailed);

    return {
      content: [
        {
          type: 'text',
          text: responseText
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error listing categories: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Format categories response using JSON data
 */
function formatCategoriesResponseFromJson(categoriesData, stats, detailed) {
  let output = '# React Bits Component Categories\n\n';

  output += `**Total Categories:** ${stats.totalCategories}\n`;
  output += `**Total Components:** ${stats.totalComponents}\n`;
  output += `**Available Tech Stacks:** ${stats.totalTechStacks}\n`;
  output += `**Data Version:** ${stats.version}\n\n`;

  // List categories
  Object.entries(categoriesData).forEach(([key, category]) => {
    output += `## ${category.name}\n`;
    output += `**Count:** ${category.count} components\n`;
    
    if (detailed) {
      output += `**Key:** \`${key}\`\n`;
      output += `**Components:** ${category.components.slice(0, 5).join(', ')}${category.components.length > 5 ? '...' : ''}\n`;
      output += `**Usage:** Use \`${key}\` as category filter when searching\n`;
    }

    output += '\n';
  });

  // Add tech stack information
  output += '## Available Tech Stacks\n\n';
  stats.techStacks.forEach(stack => {
    const stackInfo = {
      'js-css': 'JavaScript + CSS (vanilla styling)',
      'js-tailwind': 'JavaScript + Tailwind CSS',
      'ts-css': 'TypeScript + CSS (with type safety)',
      'ts-tailwind': 'TypeScript + Tailwind CSS (recommended)'
    };
    output += `- **${stack}**: ${stackInfo[stack]}\n`;
  });

  // Add usage examples
  output += '\n---\n\n';
  output += '## Usage Examples\n\n';
  output += '**Search components in a specific category:**\n';
  output += '```\nsearch-react-bits-components --category animations\n```\n\n';
  
  output += '**Search for specific functionality:**\n';
  output += '```\nsearch-react-bits-components --query "card hover"\n```\n\n';

  output += '**Get component code:**\n';
  output += '```\nget-react-bits-component --componentName spotlight-card --version ts-tailwind\n```\n\n';

  // Category highlights
  output += '## Category Highlights\n\n';

  output += '### 🎬 Animations\n';
  output += 'Perfect for adding smooth transitions and micro-interactions to your UI.\n';
  output += 'Popular: Magnet, Click Spark, Star Border\n\n';

  output += '### ✨ Text Animations\n';
  output += 'Bring your typography to life with engaging text effects.\n';
  output += 'Popular: Split Text, Blur Text, Shiny Text\n\n';

  output += '### 🧩 Components\n';
  output += 'Interactive UI elements ready to drop into your application.\n';
  output += 'Popular: Spotlight Card, Dock, Magic Bento\n\n';

  output += '### 🌈 Backgrounds\n';
  output += 'Eye-catching background effects to enhance your design.\n';
  output += 'Popular: Aurora, Particles, Liquid Chrome\n\n';

  output += `**Data generated:** ${new Date(stats.generatedAt).toLocaleString()}\n`;

  return output;
}

/**
 * Update category counts based on actual component data (legacy)
 */
function updateCategoryCounts(categoriesData, componentData) {
  const updated = { ...categoriesData };

  if (componentData) {
    // Count components in each category
    for (const [categoryKey, components] of Object.entries(componentData)) {
      const categoryName = mapCategoryKey(categoryKey);
      if (updated[categoryName]) {
        updated[categoryName].count = Object.keys(components).length;
      }
    }
  }

  return updated;
}

/**
 * Map category keys to category names
 */
function mapCategoryKey(key) {
  const mapping = {
    'animations': 'animations',
    'textAnimations': 'text-animations',
    'components': 'components',
    'backgrounds': 'backgrounds'
  };
  
  return mapping[key] || key;
}

/**
 * Format categories response
 */
function formatCategoriesResponse(categories, detailed) {
  let output = '# React Bits Component Categories\n\n';

  const totalComponents = Object.values(categories).reduce((sum, cat) => sum + (cat.count || 0), 0);
  output += `**Total Components:** ${totalComponents}\n\n`;

  // List categories
  Object.entries(categories).forEach(([key, category]) => {
    output += `## ${category.name}\n`;
    output += `**Count:** ${category.count || 0} components\n`;
    output += `**Description:** ${category.description}\n`;

    if (detailed) {
      output += `**Key:** \`${key}\`\n`;
      output += `**Usage:** Use this category key when searching with \`search-react-bits-components\`\n`;
    }

    output += '\n';
  });

  // Add usage examples
  output += '---\n\n';
  output += '## Usage Examples\n\n';
  output += '**Search components in a specific category:**\n';
  output += '```\nsearch-react-bits-components --category animations\n```\n\n';
  
  output += '**Search for specific functionality:**\n';
  output += '```\nsearch-react-bits-components --query "card hover"\n```\n\n';

  output += '**Get component code:**\n';
  output += '```\nget-react-bits-component --componentName stack --version js-tailwind\n```\n\n';

  // Category-specific recommendations
  output += '## Category Highlights\n\n';

  output += '### 🎬 Animations\n';
  output += 'Perfect for adding smooth transitions and micro-interactions to your UI.\n';
  output += 'Popular components: stack, dock, elastic-slider\n\n';

  output += '### ✨ Text Animations\n';
  output += 'Bring your typography to life with engaging text effects.\n';
  output += 'Great for headers, hero sections, and call-to-action elements.\n\n';

  output += '### 🧩 Components\n';
  output += 'Interactive UI elements ready to drop into your application.\n';
  output += 'Popular components: spotlight-card, rolling-gallery, infinite-scroll\n\n';

  output += '### 🌈 Backgrounds\n';
  output += 'Eye-catching background effects to enhance your design.\n';
  output += 'Popular components: particles, liquid-chrome, lightning\n\n';

  // Tech stack information
  output += '## Available Tech Stacks\n\n';
  output += 'Each component is available in 4 different versions:\n\n';
  output += '- **js-css**: JavaScript + CSS (vanilla styling)\n';
  output += '- **js-tailwind**: JavaScript + Tailwind CSS\n';
  output += '- **ts-css**: TypeScript + CSS (with type safety)\n';
  output += '- **ts-tailwind**: TypeScript + Tailwind CSS (best of both worlds)\n\n';

  output += 'Choose the version that matches your project setup!\n';

  return output;
}
